const body = $input.first().json.body;
const { userId, achievementType, data } = body;

const shareWorthy = {
  'first_lesson': { title: '🎓 First Lesson Complete!', share: true, reward: 1 },
  'lesson_10': { title: '📚 10 Lessons Mastered!', share: true, reward: 3 },
  'lesson_50': { title: '🏆 50 Lessons Champion!', share: true, reward: 7 },
  'lesson_100': { title: '👑 100 Lessons Legend!', share: true, reward: 14 },
  'streak_7': { title: '🔥 7-Day Learning Streak!', share: true, reward: 3 },
  'streak_30': { title: '💎 30-Day Streak Master!', share: true, reward: 14 },
  'first_contribution': { title: '🌟 First Contribution!', share: true, reward: 2 },
  'top_contributor': { title: '🥇 Top Contributor of the Week!', share: true, reward: 7 },
  'exam_passed': { title: '✅ Exam Passed!', share: true, reward: 1 }
};

const achievement = shareWorthy[achievementType];
if (!achievement) return [{ json: { skip: true } }];

return [{
  json: {
    userId,
    achievementType,
    ...achievement,
    userName: data?.userName || 'Student',
    userEmail: data?.email || '',
    stats: data?.stats || {},
    skip: false
  }
}];

