const response = $input.first().json.message.content;
let parsed;
try { parsed = JSON.parse(response); } catch(e) {
  const m = response.match(/```(?:json)?\s*([\s\S]*?)```/);
  parsed = JSON.parse(m[1].trim());
}
const prev = $('Classify Achievement').first().json;
return [{ json: { ...prev, ...parsed } }];
